node <<'NODE'
const fs = require('node:fs')
const sampleRate = 22050
const seconds = 32
const frames = sampleRate * seconds
const left = new Float32Array(frames)
const right = new Float32Array(frames)
const chords = [
  [48, 55, 60, 64, 67, 71],
  [45, 52, 57, 60, 64, 67],
  [41, 48, 53, 57, 60, 64],
  [43, 50, 55, 57, 62, 67],
]
const midiFrequency = midi => 440 * 2 ** ((midi - 69) / 12)
function addPluck(midi, start, gain, pan = 0) {
  const startFrame = Math.floor(start * sampleRate)
  const count = Math.min(Math.floor(4.4 * sampleRate), frames - startFrame)
  const base = midiFrequency(midi)
  for (let i = 0; i < count; i++) {
    const t = i / sampleRate
    const attack = Math.min(1, t / 0.018)
    const decay = Math.exp(-1.35 * t)
    const fundamental = Math.sin(2 * Math.PI * base * t)
    const harmonics = 0.32 * Math.sin(2 * Math.PI * base * 2.01 * t) + 0.11 * Math.sin(2 * Math.PI * base * 3.98 * t)
    const sample = gain * attack * decay * (fundamental + harmonics)
    const frame = startFrame + i
    left[frame] += sample * (pan > 0 ? 1 - pan * 0.22 : 1)
    right[frame] += sample * (pan < 0 ? 1 + pan * 0.22 : 1)
  }
}
for (let bar = 0; bar < chords.length; bar++) {
  const chord = chords[bar]
  const start = bar * 8
  addPluck(chord[0], start, 0.19, -0.1)
  addPluck(chord[2], start + 0.35, 0.12, 0.12)
  addPluck(chord[4], start + 1.7, 0.1, -0.18)
  addPluck(chord[3], start + 3.3, 0.105, 0.18)
  addPluck(chord[5], start + 5.0, 0.09, -0.12)
  addPluck(chord[4], start + 6.55, 0.085, 0.12)
}
const fadeFrames = Math.floor(sampleRate * 0.35)
for (let i = 0; i < frames; i++) {
  const edge = Math.min(1, i / fadeFrames, (frames - 1 - i) / fadeFrames)
  left[i] *= edge
  right[i] *= edge
}
let peak = 0
for (let i = 0; i < frames; i++) peak = Math.max(peak, Math.abs(left[i]), Math.abs(right[i]))
const scale = 0.28 / peak
const wav = Buffer.alloc(44 + frames * 4)
const write = (offset, text) => wav.write(text, offset, 'ascii')
write(0, 'RIFF')
wav.writeUInt32LE(wav.length - 8, 4)
write(8, 'WAVE')
write(12, 'fmt ')
wav.writeUInt32LE(16, 16)
wav.writeUInt16LE(1, 20)
wav.writeUInt16LE(2, 22)
wav.writeUInt32LE(sampleRate, 24)
wav.writeUInt32LE(sampleRate * 4, 28)
wav.writeUInt16LE(4, 32)
wav.writeUInt16LE(16, 34)
write(36, 'data')
wav.writeUInt32LE(frames * 4, 40)
for (let i = 0; i < frames; i++) {
  wav.writeInt16LE(Math.max(-32768, Math.min(32767, Math.round(left[i] * scale * 32767))), 44 + i * 4)
  wav.writeInt16LE(Math.max(-32768, Math.min(32767, Math.round(right[i] * scale * 32767))), 46 + i * 4)
}
fs.writeFileSync('public/piano-doux.wav', wav)
console.log(`Wrote ${wav.length} bytes, ${seconds}s stereo loop at ${sampleRate} Hz`)
